using System.Text;
using KyberWeave.Core.Squad.Deployment;
using KyberWeave.Core.Squad.Rendering;
using KyberWeave.Tests.Fixtures;
using Xunit;

namespace KyberWeave.Tests;

/// <summary>
/// Guards the project-scope Arbiter shims against the approved main-branch golden bytes.
/// The project renders must stay byte-identical to the main branch; the current branch
/// regressed by inserting a whitespace-only line while composing the global command string.
/// </summary>
public sealed class ArbiterProjectShimByteIdentityTests : IDisposable
{
    private readonly ArbiterSquadFixture _fixture = ArbiterSquadFixture.Create();

    public void Dispose() => _fixture.Dispose();

    [Fact]
    public async Task OpenCode_ProjectScopeShim_IsByteIdenticalToMain()
    {
        SquadRenderResult result = await new SquadRendererRegistry([new OpenCodeRenderer()]).RenderAsync(new SquadRenderRequest(
            SourceDirectory: _fixture.Path,
            Targets: [SquadTarget.OpenCode],
            Scope: SquadDeploymentScope.Project,
            Arbiter: new SquadArbiterWiring(Enabled: true, HookTimeoutSeconds: 5)));

        Assert.True(result.Success, string.Join("; ", result.Errors));
        SquadDeploymentFile shim = Assert.Single(result.Files, file => file.RelativePath == ".opencode/plugins/kyber-arbiter.ts");
        Assert.Equal(OpenCodeMainGolden, Encoding.UTF8.GetString(shim.Content.Span));
    }

    [Fact]
    public async Task Kilo_ProjectScopeShim_IsByteIdenticalToMain()
    {
        SquadRenderResult result = await new SquadRendererRegistry([new KiloRenderer()]).RenderAsync(new SquadRenderRequest(
            SourceDirectory: _fixture.Path,
            Targets: [SquadTarget.Kilo],
            Scope: SquadDeploymentScope.Project,
            Arbiter: new SquadArbiterWiring(Enabled: true, HookTimeoutSeconds: 5)));

        Assert.True(result.Success, string.Join("; ", result.Errors));
        SquadDeploymentFile shim = Assert.Single(result.Files, file => file.RelativePath == ".kilo/plugin/kyber-arbiter.ts");
        Assert.Equal(KiloMainGolden, Encoding.UTF8.GetString(shim.Content.Span));
    }

    [Fact]
    public async Task Pi_ProjectScopeShim_IsByteIdenticalToMain()
    {
        SquadRenderResult result = await new SquadRendererRegistry([new PiRenderer()]).RenderAsync(new SquadRenderRequest(
            SourceDirectory: _fixture.Path,
            Targets: [SquadTarget.Pi],
            Scope: SquadDeploymentScope.Project,
            Arbiter: new SquadArbiterWiring(Enabled: true, HookTimeoutSeconds: 5)));

        Assert.True(result.Success, string.Join("; ", result.Errors));
        SquadDeploymentFile shim = Assert.Single(result.Files, file => file.RelativePath == ".pi/extensions/kyber-arbiter.ts");
        Assert.Equal(PiMainGolden, Encoding.UTF8.GetString(shim.Content.Span));
    }
    private static readonly string OpenCodeMainGolden = Encoding.UTF8.GetString(Convert.FromBase64String(""));

    private static readonly string KiloMainGolden = Encoding.UTF8.GetString(Convert.FromBase64String(""));

    private static readonly string PiMainGolden = Encoding.UTF8.GetString(Convert.FromBase64String(""));

}
